    const CONTROLS = [
        "a[href]",
        "area[href]",
        "button",
        "input:not([type=hidden])",
        "select",
        "textarea",
        "summary",
        "[tabindex='0']",
    ].join(",");
    const COMPOSITE_ROLES = new Set([
        "grid",
        "listbox",
        "menu",
        "menubar",
        "radiogroup",
        "tablist",
        "toolbar",
        "tree",
        "treegrid",
    ]);
